// Default-construct an empty token and validate basic properties
pxr::TfToken t;
// Empty token should report size 0 and IsEmpty true
FUZZ_ASSERT(t.size() == 0, "Default TfToken should have size 0");
FUZZ_ASSERT(t.IsEmpty(), "Default TfToken should be empty");
// GetText/data must be non-null C-string pointers (may point to shared empty string)
const char *p1 = t.GetText();
const char *p2 = t.data();
FUZZ_ASSERT(p1 != nullptr && p2 != nullptr, "GetText/data must return non-null");
// They should be null-terminated and equal for an empty token
FUZZ_ASSERT(p1[0] == '\0' && p2[0] == '\0', "Empty token text must be empty string");
// Hash is stable across repeated calls
size_t h1 = t.Hash();
size_t h2 = t.Hash();
FUZZ_ASSERT(h1 == h2, "Hash must be stable for the same token");

// Generate arbitrary string input; Find should return existing token or empty token
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
// If s has never been interned, Find returns an empty token; otherwise non-empty.
// We cannot know interning state here, but we can validate invariants:
if (t.IsEmpty()) {
    FUZZ_ASSERT(t.size() == 0, "Empty Find result must have size 0");
} else {
    FUZZ_ASSERT(t.size() == s.size(), "Found token length should match input length when non-empty");
}
// Hash must be stable
size_t h1 = t.Hash();
size_t h2 = t.Hash();
FUZZ_ASSERT(h1 == h2, "Hash must be stable");

// Create a token from fuzz string by interning via Find (non-throwing path)
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
size_t h1 = t.Hash();
size_t h2 = t.Hash();
FUZZ_ASSERT(h1 == h2, "Hash must be stable across repeated calls");
// Copy should preserve identity-based hash
pxr::TfToken tCopy = t;
FUZZ_ASSERT(h1 == tCopy.Hash(), "Hash must be equal for copies of the same token");

// Validate size aligns with the C-string length
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
size_t n = t.size();
// For empty tokens, size must be 0
if (t.IsEmpty()) {
    FUZZ_ASSERT(n == 0, "Empty token must report size 0");
} else {
    // Non-empty returned by Find implies same length as input
    FUZZ_ASSERT(n == s.size(), "Token size should match input length for non-empty Find result");
}
// C-string from GetText must have matching length
const char *p = t.GetText();
FUZZ_ASSERT(p != nullptr, "GetText must be non-null");
FUZZ_ASSERT(strlen(p) == n, "GetText C-string length must match size()");

// Create token and access its text pointer. The pointer must remain valid while token is alive in-scope.
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
const char *text = t.GetText();
FUZZ_ASSERT(text != nullptr, "GetText must not return null");
// Validate null-termination and length agreement
size_t n = t.size();
FUZZ_ASSERT(strlen(text) == n, "GetText length must equal token size");
// Access a few characters safely (if any)
if (n > 0) {
    volatile unsigned char c0 = static_cast<unsigned char>(text[0]);
    (void)c0;
}
if (n > 1) {
    volatile unsigned char c1 = static_cast<unsigned char>(text[n - 1]);
    (void)c1;
}
// Do not use 'text' beyond the lifetime of 't' (ends at stub end).

// data() is an alias of GetText(); exercise both and compare pointers/content
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
const char *p1 = t.GetText();
const char *p2 = t.data();
FUZZ_ASSERT(p1 != nullptr && p2 != nullptr, "GetText/data must be non-null");
FUZZ_ASSERT(strcmp(p1, p2) == 0, "GetText() and data() should yield identical C-strings");
FUZZ_ASSERT(strlen(p1) == t.size(), "C-string length must match size()");

// Get a const reference to the underlying string and validate consistency
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
const std::string &rs = t.GetString();
// The reference must be usable while 't' is alive
FUZZ_ASSERT(rs.size() == t.size(), "GetString().size must equal token size()");
// For non-empty tokens produced by Find, contents should match 's'
if (!t.IsEmpty()) {
    FUZZ_ASSERT(rs.size() == s.size(), "Non-empty token string length should match input");
}
// Hash stability remains intact when observing via GetString
size_t h1 = t.Hash();
size_t h2 = t.Hash();
FUZZ_ASSERT(h1 == h2, "Hash stable while using GetString ref");

// Create two tokens from fuzz inputs and swap them
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
pxr::TfToken a = pxr::TfToken::Find(s1);
pxr::TfToken b = pxr::TfToken::Find(s2);
size_t aSize = a.size();
size_t bSize = b.size();
a.Swap(b);
// After swap, sizes should be exchanged
FUZZ_ASSERT(a.size() == bSize && b.size() == aSize, "Swap must exchange contents in O(1)");
// Swap back to restore
b.Swap(a);
FUZZ_ASSERT(a.size() == aSize && b.size() == bSize, "Second swap should restore original state");

// Build two tokens; possibly equal by deriving the second from the first
std::string base = FUZZ_PARAM_STR();
pxr::TfToken t1 = pxr::TfToken::Find(base);
// Decide whether to make equal or not based on a fuzz bit
bool makeEqual = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
pxr::TfToken t2 = makeEqual ? t1 : pxr::TfToken::Find(FUZZ_PARAM_STR());
bool eq = (t1 == t2);
if (makeEqual) {
    FUZZ_ASSERT(eq, "Tokens should compare equal when sourced identically");
} else {
    // May still be equal if random strings match; check basic invariant symmetry
    bool eq2 = (t2 == t1);
    FUZZ_ASSERT(eq == eq2, "operator== must be symmetric");
}
// Consistency with size equality when equal
if (eq) {
    FUZZ_ASSERT(t1.size() == t2.size(), "Equal tokens must have same size");
}

// operator!= against std::string
std::string sToken = FUZZ_PARAM_STR();
std::string sOther = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(sToken);
bool ne = (t != sOther);
// If we ensure equality of contents, operator!= must be false
bool forceEqual = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
if (forceEqual) {
    ne = (t != sToken);
    FUZZ_ASSERT(!ne, "Token should not be != its own string");
}
// Basic sanity: negation aligns with equality against string
bool eqStr = !ne;
if (eqStr) {
    if (!t.IsEmpty()) {
        FUZZ_ASSERT(t.size() == sToken.size(), "Equal-to-string implies same size");
    }
}

// Compare two tokens lexicographically
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
pxr::TfToken a = pxr::TfToken::Find(s1);
pxr::TfToken b = pxr::TfToken::Find(s2);
bool lt = (a < b);
bool gt = (b < a);
FUZZ_ASSERT(!(lt && gt), "Strict weak ordering: cannot be both a<b and b<a");
if (!lt && !gt) {
    // Then they are equivalent in ordering; if truly identical tokens, sizes must match
    if (a == b) {
        FUZZ_ASSERT(a.size() == b.size(), "Equal tokens must have same size");
    }
}

// Compare two tokens via operator>
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
pxr::TfToken a = pxr::TfToken::Find(s1);
pxr::TfToken b = pxr::TfToken::Find(s2);
bool gt = (a > b);
bool lt = (a < b);
FUZZ_ASSERT(!(gt && lt), "> and < cannot both be true");
if (!gt && !lt) {
    // Then they are equivalent; ensure consistency with ==
    bool eq = (a == b);
    if (eq) {
        FUZZ_ASSERT(a.size() == b.size(), "Equal tokens must have same size");
    }
}

// Compare two tokens via operator>= and ensure consistency with <
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
pxr::TfToken a = pxr::TfToken::Find(s1);
pxr::TfToken b = pxr::TfToken::Find(s2);
bool ge = (a >= b);
bool lt = (a < b);
FUZZ_ASSERT(ge == !lt, ">= must be logical negation of <");

// Compare two tokens via operator<= and ensure consistency with >
std::string s1 = FUZZ_PARAM_STR();
std::string s2 = FUZZ_PARAM_STR();
pxr::TfToken a = pxr::TfToken::Find(s1);
pxr::TfToken b = pxr::TfToken::Find(s2);
bool le = (a <= b);
bool gt = (a > b);
FUZZ_ASSERT(le == !gt, "<= must be logical negation of >");

// Validate IsEmpty coherence with size and text pointer
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
bool empty = t.IsEmpty();
FUZZ_ASSERT(empty == (t.size() == 0), "IsEmpty must agree with size()==0");
const char *p = t.GetText();
FUZZ_ASSERT(p != nullptr, "GetText must be non-null");
FUZZ_ASSERT((p[0] == '\0') == empty, "Empty implies first char is NUL");

// Query immortality. True result is reliable; false may become stale.
// We simply ensure it is a boolean and that repeated calls are consistent within this scope.
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
bool imm1 = t.IsImmortal();
bool imm2 = t.IsImmortal();
FUZZ_ASSERT(imm1 == imm2, "IsImmortal should not flap during token lifetime in this scope");

// Build a vector<string> by splitting a fuzz blob to avoid macro-in-loop limitation
std::string blob = FUZZ_PARAM_STR();
std::vector<std::string> sv;
sv.reserve(32);
// Split on whitespace and commas to get a mix of empty and non-empty segments
std::string current;
for (char ch : blob) {
    if (ch == ' ' || ch == '\n' || ch == '\t' || ch == ',') {
        sv.push_back(current);
        current.clear();
        if (sv.size() >= 64) break; // limit size for performance
    } else {
        current.push_back(ch);
        if (current.size() > 256) { sv.push_back(current); current.clear(); }
    }
}
sv.push_back(current);
// Convert to tokens
std::vector<pxr::TfToken> tv = pxr::TfToTokenVector(sv);
// Basic invariants: sizes should align
FUZZ_ASSERT(tv.size() == sv.size(), "Converted vector must have same length");
for (size_t i = 0; i < tv.size(); ++i) {
    // Empty strings may map to empty token; non-empty may still be empty if not interned by Find semantics,
    // but TfToTokenVector interns, so non-empty strings should produce non-empty tokens.
    if (!sv[i].empty()) {
        FUZZ_ASSERT(!tv[i].IsEmpty(), "Non-empty input string should yield non-empty token");
        FUZZ_ASSERT(tv[i].size() == sv[i].size(), "Token length must match input string length");
    } else {
        FUZZ_ASSERT(tv[i].IsEmpty(), "Empty input string should yield empty token");
    }
}
// Hash stability spot-check
if (!tv.empty()) { (void)tv[0].Hash(); }

// Create a vector of tokens from fuzz input by splitting, then convert to strings
std::string blob = FUZZ_PARAM_STR();
std::vector<std::string> sv;
sv.reserve(32);
std::string cur;
for (char ch : blob) {
    if (ch == ' ' || ch == '\n' || ch == '\t' || ch == ',') {
        sv.push_back(cur);
        cur.clear();
        if (sv.size() >= 64) break;
    } else {
        cur.push_back(ch);
        if (cur.size() > 256) { sv.push_back(cur); cur.clear(); }
    }
}
sv.push_back(cur);
std::vector<pxr::TfToken> tv = pxr::TfToTokenVector(sv);
std::vector<std::string> back = pxr::TfToStringVector(tv);
FUZZ_ASSERT(back.size() == tv.size(), "Roundtrip vector must preserve size");
for (size_t i = 0; i < tv.size(); ++i) {
    // The returned strings should match token contents
    FUZZ_ASSERT(back[i].size() == tv[i].size(), "Extracted string length must match token size");
    // If token was empty, string should be empty
    if (tv[i].IsEmpty()) {
        FUZZ_ASSERT(back[i].empty(), "Empty token should yield empty string");
    }
}
// Optional: join to exercise string usage
std::string joined;
for (size_t i = 0; i < back.size() && i < 8; ++i) { joined += back[i]; if (i + 1 < back.size()) joined.push_back(','); }

// Compute hash via free function and ensure it matches member Hash
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
size_t h1 = pxr::hash_value(t);
size_t h2 = t.Hash();
FUZZ_ASSERT(h1 == h2, "hash_value must delegate to TfToken::Hash");

// Stream insertion into a standard ostringstream using unqualified operator<< (ADL finds pxr overload)
std::string s = FUZZ_PARAM_STR();
pxr::TfToken t = pxr::TfToken::Find(s);
std::ostringstream oss;
std::ostream &ref = (oss << t); // should return the same stream reference
FUZZ_ASSERT(&ref == static_cast<std::ostream*>(&oss), "operator<< must return the provided stream reference");
FUZZ_ASSERT(oss.good(), "ostream should remain good after operator<<");
// Compare produced output with token content length; empty tokens yield empty output
std::string out = oss.str();
FUZZ_ASSERT(out.size() == t.size(), "operator<< output length must match token size");
// Chaining should continue writing to the same stream without errors
oss << t;
FUZZ_ASSERT(oss.good(), "ostream should remain good after chained operator<<");
